"""Applies Chromium's Android edits to the headers generated by ./configure.

APR's ./configure is run on Linux (see README.chromium). This script edits
the generated include/apr.h and include/arch/unix/apr_private.h for Android
in place.

Usage: apply_android_edits.py <apr.h> <apr_private.h>
"""
import re
import sys

NDK_R16_COMMENT = """\
// Removed due to incompatability with Android NDK r16
// On older NDK versions, _POSIX_THREAD_SAFE_FUNCTIONS was unconditionally
// #undef'd. On newer versions, it is unconditionally defined as the Posix
// version. This causes issues in
// user/unix/groupinfo.c, as APR seems to unconditionally define
// HAVE_GETGRGID_R AND HAVE_GETGRNAM_R, and the only thing that was previously
// preventing it from using getgrgid_r/getgrnam_r was
// _POSIX_THREAD_SAFE_FUNCTIONS being undefined.
"""


def sub_one(text, pattern, repl):
  new, n = re.subn(pattern, repl, text, flags=re.M)
  if n != 1:
    sys.exit('expected one match for %r, got %d' % (pattern, n))
  return new


def set_value(text, name, value):
  return sub_one(text, r'^#define %s(\s+)\S+(.*)$' % name,
                 r'#define %s\g<1>%s\g<2>' % (name, value))


def comment_out(text, name):
  # "#define NAME VALUE" -> "/* #define NAME VALUE */"
  return sub_one(text, r'^(#define %s\b.*?)\s*$' % name, r'/* \1 */')


def undef(text, name):
  # "#define NAME VALUE" -> "/* #undef NAME */"
  return sub_one(text, r'^#define %s\b.*$' % name, '/* #undef %s */' % name)


def define(text, name, value):
  # "/* #undef NAME */" -> "#define NAME VALUE"
  return sub_one(text, r'^/\* #undef %s \*/$' % name,
                 '#define %s %s' % (name, value))


def edit_apr_h(t):
  # Not available on Android.
  t = set_value(t, 'APR_HAVE_NETINET_SCTP_H', '0')
  t = set_value(t, 'APR_HAVE_SCTP', '0')
  t = set_value(t, 'APR_HAS_OS_UUID', '0')
  t = set_value(t, 'APR_HAS_SYSVSEM_SERIALIZE', '0')
  # Bionic has no shm_open().
  t = set_value(t, 'APR_USE_SHMEM_MMAP_SHM', '0')
  return t


def edit_apr_private_h(t):
  for name in [
      'DIRENT_INODE',
      'GETSERVBYNAME_R_GLIBC2',
      'HAVE_ACCEPT4',
      'HAVE_DUP3',
      'HAVE_EPOLL_CREATE1',
      'HAVE_GETIFADDRS',
      'HAVE_GETPASS',
      'HAVE_NL_LANGINFO',
      'HAVE_PTHREAD_MUTEX_ROBUST',
      'HAVE_SOCK_CLOEXEC',
      'HAVE_STRUCT_STAT_ST_ATIM_TV_NSEC',
      'HAVE_STRUCT_STAT_ST_CTIM_TV_NSEC',
      'HAVE_STRUCT_STAT_ST_MTIM_TV_NSEC',
      'HAVE_SYS_SEM_H',
      'HAVE_SYS_SHM_H',
      'HAVE_UUID_UUID_H',
  ]:
    t = comment_out(t, name)
  t = sub_one(t, r'^#define HAVE_GETGRGID_R 1$',
              NDK_R16_COMMENT + '// #define HAVE_GETGRGID_R 1')
  t = sub_one(t, r'^#define HAVE_GETGRNAM_R 1$',
              '// Removed due to incompatability with Android NDK r16\n'
              '// #define HAVE_GETGRNAM_R 1')
  # Bionic declares sys_siglist; newer glibc does not.
  t = set_value(t, 'HAVE_DECL_SYS_SIGLIST', '1')
  # getrandom() needs API level 28; keep reading /dev/urandom.
  t = undef(t, 'HAVE_GETRANDOM')
  t = set_value(t, 'HAVE_DECL_SYS_GETRANDOM', '0')
  t = undef(t, 'SYS_RANDOM')
  t = define(t, 'DEV_RANDOM', '"/dev/urandom"')
  # No SysV semaphores (semtimedop() needs API level 26), no shm_open().
  t = undef(t, 'HAVE_SEMOP')
  t = undef(t, 'HAVE_SEMTIMEDOP')
  t = undef(t, 'USE_SHMEM_MMAP_SHM')
  # 32-bit x86 aligns 64-bit integers to 4 bytes, so 64-bit atomic builtins
  # on apr_uint64_t are misaligned there (-Watomic-alignment). Use the
  # mutex-based fallback (atomic/unix/mutex64.c) on that architecture.
  for name in ['HAVE_ATOMIC_BUILTINS64', 'HAVE__ATOMIC_BUILTINS64']:
    t = sub_one(t, r'^#define %s 1$' % name,
                '#if !defined(__i386__)\n#define %s 1\n#endif' % name)
  return t


def main():
  apr_h, apr_private_h = sys.argv[1:3]
  for path, edit in [(apr_h, edit_apr_h), (apr_private_h, edit_apr_private_h)]:
    with open(path) as f:
      text = f.read()
    with open(path, 'w') as f:
      f.write(edit(text))


if __name__ == '__main__':
  main()
